from typing import List

class Solution:
    def minInterval(self, intervals: List[List[int]], queries: List[int]) -> List[int]:
        answer = []
        for q in queries:
            best = float("inf")
            for left, right in intervals:
                if left <= q <= right:
                    best = min(best, right - left + 1)
            answer.append(-1 if best == float("inf") else best)
        return answer

